const money=new Intl.NumberFormat('es-ES',{style:'currency',currency:'EUR'});
const node=(doc,tag,className,text)=>{const value=doc.createElement(tag);if(className)value.className=className;if(text!==undefined)value.textContent=text;return value;};
export function attendeeTotals(rows=[]){return rows.reduce((total,row)=>({pilots:total.pilots+1,attendees:total.attendees+Number(row.attendees||0),calcotada:total.calcotada+Number(row.calcotada||0),vegetarian:total.vegetarian+Number(row.vegetarian||0),childMenu:total.childMenu+Number(row.childMenu||0),depositCents:total.depositCents+Number(row.depositCents||0),balanceCents:total.balanceCents+Number(row.balanceCents||0),paid:total.paid+(row.paid?1:0)}),{pilots:0,attendees:0,calcotada:0,vegetarian:0,childMenu:0,depositCents:0,balanceCents:0,paid:0});}

export function createEventAttendeeManager({doc=document,event,api,expanded=false,readOnly=false}){
 const details=node(doc,'details','event-attendees'+(expanded?' is-page':''));details.dataset.eventAttendees='';details.dataset.eventId=event.id;if(expanded)details.open=true;
 const summary=node(doc,'summary','event-attendees-summary'),title=node(doc,'span','event-attendees-title','Lista de asistentes'),privacy=node(doc,'small','event-attendees-private',readOnly?'Consulta · edición solo administradores':'Administración de asistentes'),badge=node(doc,'b','event-attendees-badge','Abrir');summary.append(title,privacy,badge);details.append(summary);
 const body=node(doc,'div','event-attendees-body'),toolbar=node(doc,'div','event-attendees-toolbar'),totals=node(doc,'div','event-attendees-totals'),share=node(doc,'a','event-attendees-share','Compartir por WhatsApp'),add=node(doc,'button','event-attendees-add','Añadir asistente');add.type='button';share.href='https://wa.me/';share.target='_blank';share.rel='noopener noreferrer';share.hidden=true;share.setAttribute('aria-label','Preparar la lista de asistentes para compartir por WhatsApp');share.title='Incluye nombres y el total de asistentes, sin matrículas ni datos de pago.';toolbar.append(totals,share,add);add.hidden=readOnly;
 const status=node(doc,'p','event-attendees-status',expanded?'Cargando asistentes…':'Abre la lista para cargar los asistentes.');status.setAttribute('role','status');status.setAttribute('aria-live','polite');
 const form=node(doc,'form','event-attendee-form');form.hidden=true;form.innerHTML='<input type="hidden" name="id"><div class="event-attendee-fields"><label>Nombre piloto<input name="pilotName" required minlength="2" maxlength="100" autocomplete="name"></label><label>Asistentes<input name="attendees" type="number" required min="1" max="99" value="1" inputmode="numeric"></label><label>Niños<input name="children" type="number" min="0" max="99" value="0"></label><label>Matrícula<input name="plate" maxlength="20" autocomplete="off"></label><label>Calçotada<input name="calcotada" type="number" min="0" max="99" value="0" inputmode="numeric"></label><label>Calçotada sin<input name="calcotadaWithout" type="number" min="0" max="99" value="0"></label><label>Vegetariano<input name="vegetarian" type="number" min="0" max="99" value="0" inputmode="numeric"></label><label>Infantil<input name="childMenu" type="number" min="0" max="99" value="0" inputmode="numeric"></label><label>Postre<input name="dessert" maxlength="200"></label><label>Paga y señal (€)<input name="depositEuros" type="number" min="0" max="99999.99" step="0.01" value="0" inputmode="decimal"></label><label>Resto (€)<input name="balanceEuros" type="number" min="0" max="99999.99" step="0.01" value="0" inputmode="decimal"></label><label class="event-attendee-paid"><input name="paid" type="checkbox"> Pagado</label></div><div class="event-attendee-form-actions"><button type="submit">Guardar</button><button type="button" data-attendee-cancel>Cancelar</button></div><p data-attendee-form-status role="status"></p>';
 const tableWrap=node(doc,'div','event-attendees-table-wrap'),table=node(doc,'table','event-attendees-table');table.innerHTML='<thead><tr><th>Nombre piloto</th><th>Asistentes</th><th>Niños</th><th>Matrícula</th><th>Calçotada</th><th>Calçotada sin</th><th>Vegetariano</th><th>Infantil</th><th>Postre</th><th>Paga y señal</th><th>Resto</th><th>Pagado</th><th><span class="sr-only">Acciones</span></th></tr></thead><tbody></tbody>';tableWrap.append(table);body.append(toolbar,status,form,tableWrap);details.append(body);
 let rows=[],loaded=false,loading=false;
 const path=id=>'events/'+encodeURIComponent(event.id)+'/attendees'+(id?'/'+encodeURIComponent(id):'');
 function resetForm(){form.reset();form.elements.id.value='';for(const name of ['attendees','children','calcotada','calcotadaWithout','vegetarian','childMenu'])form.elements[name].value=name==='attendees'?'1':'0';for(const name of ['depositEuros','balanceEuros'])form.elements[name].value='0';form.hidden=true;form.querySelector('[data-attendee-form-status]').textContent='';add.textContent='Añadir asistente';}
 function edit(row){form.hidden=false;form.elements.id.value=row.id;for(const name of ['pilotName','attendees','children','plate','calcotada','calcotadaWithout','vegetarian','childMenu','dessert'])form.elements[name].value=row[name]??'';form.elements.depositEuros.value=(row.depositCents/100).toFixed(2);form.elements.balanceEuros.value=(row.balanceCents/100).toFixed(2);form.elements.paid.checked=!!row.paid;add.textContent='Editando asistente';form.scrollIntoView({block:'start',behavior:'instant'});form.elements.pilotName.focus({preventScroll:true});}
 function shareMessage(){const total=attendeeTotals(rows),date=new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(event.date+'T12:00:00Z'));const lines=['Lista de asistentes · '+event.title,date+(event.time?' · '+event.time:''),...rows.map((row,index)=>(index+1)+'. '+row.pilotName),'',rows.length+' pilotos · '+total.attendees+' asistentes.'];return lines.join(String.fromCharCode(10));}
 function render(){const total=attendeeTotals(rows);share.hidden=readOnly||!rows.length;if(rows.length)share.href='https://wa.me/?text='+encodeURIComponent(shareMessage());totals.replaceChildren();for(const [label,value]of [['Pilotos',total.pilots],['Asistentes',total.attendees],['Menús',total.calcotada+total.vegetarian+total.childMenu],['Pagados',total.paid]]){const item=node(doc,'span');item.append(node(doc,'small','',label),node(doc,'strong','',String(value)));totals.append(item);}const tbody=table.tBodies[0];tbody.replaceChildren();for(const row of rows){const tr=node(doc,'tr');for(const [label,value]of [['Nombre piloto',row.pilotName],['Asistentes',row.attendees],['Niños',row.children||0],['Matrícula',row.plate||'—'],['Calçotada',row.calcotada],['Calçotada sin',row.calcotadaWithout||0],['Vegetariano',row.vegetarian],['Infantil',row.childMenu],['Postre',row.dessert||'—'],['Paga y señal',money.format(row.depositCents/100)],['Resto',money.format(row.balanceCents/100)],['Pagado',row.paid?'Sí':'No']]){const td=node(doc,'td','',String(value));td.dataset.label=label;if(label==='Paga y señal'||label==='Resto'){const cents=Number(label==='Paga y señal'?row.depositCents:row.balanceCents);td.classList.add('attendee-amount',cents===0?'attendee-amount-zero':label==='Paga y señal'||row.paid?'attendee-amount-paid':'attendee-amount-due');}tr.append(td);}const actions=node(doc,'td','event-attendee-row-actions');actions.dataset.label='Acciones';const editButton=node(doc,'button','','Editar'),removeButton=node(doc,'button','','Eliminar');editButton.type=removeButton.type='button';editButton.addEventListener('click',()=>edit(row));removeButton.addEventListener('click',async()=>{if(!confirm('¿Eliminar a '+row.pilotName+' de la lista?'))return;removeButton.disabled=true;try{await api(path(row.id),'DELETE');rows=rows.filter(item=>item.id!==row.id);render();status.textContent='Asistente eliminado de la lista.';}catch(error){status.textContent=error.message;removeButton.disabled=false;}});if(!readOnly)actions.append(editButton,removeButton);tr.append(actions);tbody.append(tr);}tableWrap.hidden=!rows.length;status.textContent=rows.length?`${rows.length} ${rows.length===1?'piloto apuntado':'pilotos apuntados'} · ${total.attendees} asistentes · Señales ${money.format(total.depositCents/100)} · Resto ${money.format(total.balanceCents/100)}`:'Todavía no hay asistentes apuntados.';badge.textContent=details.open?(expanded?'Abierta':'Cerrar'):rows.length?String(rows.length):'Vacía';}
 async function load(force=false){if(loading||loaded&&!force)return;loading=true;status.textContent='Cargando asistentes…';try{rows=await api(path());loaded=true;render();}catch(error){status.textContent=error.message;}finally{loading=false;}}
 summary.addEventListener('click',event=>{if(expanded){event.preventDefault();return;}if(!details.open)queueMicrotask(()=>void load());});
 details.addEventListener('toggle',()=>{if(expanded&&!details.open){details.open=true;return;}badge.textContent=details.open?(expanded?'Abierta':'Cerrar'):rows.length?String(rows.length):'Abrir';if(details.open)void load();});
 add.addEventListener('click',()=>{resetForm();form.hidden=false;form.scrollIntoView({block:'start',behavior:'instant'});form.elements.pilotName.focus({preventScroll:true});});form.querySelector('[data-attendee-cancel]').addEventListener('click',resetForm);
 form.addEventListener('submit',async submit=>{submit.preventDefault();const button=form.querySelector('[type=submit]'),formStatus=form.querySelector('[data-attendee-form-status]'),id=form.elements.id.value,fields=Object.fromEntries(new FormData(form));fields.paid=form.elements.paid.checked;button.disabled=true;formStatus.textContent='Guardando…';try{const saved=await api(path(id),'POST',fields),index=rows.findIndex(item=>item.id===saved.id);if(index>=0)rows[index]=saved;else rows.push(saved);rows.sort((a,b)=>a.createdAt-b.createdAt||a.pilotName.localeCompare(b.pilotName,'es'));resetForm();render();status.textContent='Lista de asistentes actualizada.';}catch(error){formStatus.textContent=error.message;}finally{button.disabled=false;}});
 if(expanded){badge.textContent='Abierta';queueMicrotask(()=>void load());}
 return details;
}
